raw_sql:
SELECT count(*) 
FROM support.tickets 
WHERE opened_at > now() - interval '7 days';

SELECT count(*) 
FROM marts.dim_tenant
WHERE tenant_id NOT LIKE 'test-%';

SELECT marts.dim_tenant.monthly_budget_usd 
FROM marts.dim_tenant 
WHERE marts.dim_tenant.display_name = 'billing';

SELECT count(*) filter (where cache_status = 'HIT') as cache_hit_count
FROM marts.fct_requests
WHERE tenant_id not like 'test-%';

SELECT count(*) 
FROM marts.fct_outcomes 
WHERE setup = 'A_tfidf' AND split = 'tune';

SELECT count(DISTINCT gold_label) 
FROM marts.fct_outcomes 
WHERE split = 'test';

SELECT count(*) 
FROM support.tickets 
WHERE status IN ('resolved', 'closed');

SELECT COUNT(*) 
FROM support.agents 
WHERE is_active = true AND team NOT LIKE 'test-%';

SELECT count(DISTINCT ticket_id) 
FROM support.ticket_events 
WHERE event_type = 'reopened';

SELECT AVG(hourly_cost_usd) AS avg_hourly_cost_usd
FROM marts.agents
WHERE is_active AND team NOT LIKE 'test-%';
